from manim import *
import math
from math import pi, e


def _smart_text(text, font_size):
    """含非 ASCII 字符（中文/希腊字母/全角符号）用 Text（Pango 渲染，支持中文）；纯 ASCII 用 MathTex（LaTeX 渲染，支持数学公式）。"""
    return Text(text, font_size=font_size) if any(ord(c) > 127 for c in text) else MathTex(text, font_size=font_size)


class FunctionPlotScene(Scene):
    def construct(self):
        functions = {{functions}}
        x_min = {{x_min}}
        x_max = {{x_max}}
        title_text = {{title}}

        axes = Axes(
            x_range=[x_min, x_max, 1],
            y_range=[-4, 4, 1],
            axis_config={"include_numbers": True, "font_size": 18},
        )
        labels = axes.get_axis_labels(x_label="x", y_label="y")
        self.play(Create(axes), Write(labels))

        colors = [YELLOW, BLUE, GREEN, RED]
        graphs = VGroup()
        for i, expr in enumerate(functions):
            graph = axes.plot(
                lambda x, e=expr: eval(e, {"__builtins__": {}}, {"x": x, "np": np, "math": math, "pi": pi, "e": e}),
                x_range=[x_min, x_max],
                color=colors[i % len(colors)],
            )
            graphs.add(graph)
            self.play(Create(graph), run_time=1.5)

        if title_text:
            title = _smart_text(title_text, font_size=48).to_edge(UP)
            self.play(Write(title))

        self.wait(2)
